"""
Writer agent — compose final Markdown report.

FIX: No **state spread; truncated inputs to stay under TPM.
"""

from __future__ import annotations
from state import PipelineState
from llm_client import chat

SYSTEM = """
You are a senior data analyst and technical writer.
Synthesise findings into a polished Markdown report.

Structure:
# [Title]
## Executive Summary
## Key Findings
## Analysis Details
## Recommendations
## Limitations & Next Steps
---
*Report generated by the Agentic Analysis Pipeline*

Rules:
- Write for a business audience
- Use specific numbers wherever available
- Reference plots: ![title](filepath)
- Output ONLY the Markdown — no preamble
"""


def writer(state: PipelineState) -> dict:
    print("\n[Writer] Composing final report...")

    goal             = state.get("goal", "")
    analysis_results = state.get("analysis_results", [])
    tool_results     = state.get("tool_results", [])
    plots            = state.get("plots", [])
    user_query       = state.get("user_query", "")
    critic_feedback  = state.get("critic_feedback", "")

    # Truncate to stay within TPM
    all_stdout   = "\n---\n".join(
        tr.get("stdout", "")[:400] for tr in tool_results[-3:] if tr.get("success")
    )[:1500]
    all_findings = "\n\n".join(r[:400] for r in analysis_results[-4:])[:2000]

    user_prompt = f"""Original query: {user_query}
Goal: {goal}

Findings (truncated):
{all_findings or "No findings yet."}

Execution output (truncated):
{all_stdout or "No output."}

Figures (use in Markdown image syntax):
{list(dict.fromkeys(plots))}

Critic feedback to address:
{critic_feedback or "None — first draft."}

Write the complete Markdown report.
"""

    report = chat(system=SYSTEM, user=user_prompt, temperature=0.4, max_tokens=2000)
    print(f"[Writer] Report generated ({len(report)} chars)")

    # Return ONLY changed fields — no **state spread
    return {
        "final_report": report,
        "messages":     [{"role": "writer",
                          "content": f"Report generated ({len(report)} chars)"}],
    }
